<?php
declare(strict_types=1);
$private=sys_get_temp_dir().'/ectro-dataset-db-'.bin2hex(random_bytes(6));mkdir($private,0700);putenv('APP_DATA_DIR='.$private);putenv('APP_ENV=development');putenv('APP_KEY='.base64_encode(random_bytes(32)));
register_shutdown_function(function()use($private){foreach(glob($private.'/*') as $file)unlink($file);rmdir($private);});
require __DIR__.'/../app/bootstrap.php';require __DIR__.'/../app/templates.php';require __DIR__.'/../app/mysql.php';require __DIR__.'/../app/lab-api.php';
$checks=0;function dbCheck(bool $ok,string $message):void{global $checks;if(!$ok)throw new RuntimeException($message);$checks++;}function dbReject(int $status,callable $fn):void{try{$fn();throw new RuntimeException('Expected rejection');}catch(ApiError $e){dbCheck($e->status===$status,$e->getMessage());}}
foreach(['a','b'] as $name){$id=id();query('INSERT INTO users(id,name,email,password,role,created_at) VALUES(?,?,?,?,?,?)',[$id,$name,$name.'@example.test','unused','user',now()]);${$name}=one('SELECT * FROM users WHERE id=?',[$id]);}
$pid=createProject($a,'Import','web');$other=createProject($b,'Other','web');$unconnected=createProject($a,'Unconnected','web');$data=['project'=>$pid,'scope'=>'project'];
dbCheck(datasetDatabases($a,$data)['databases']===[],'No fabricated sources');dbReject(404,fn()=>datasetDatabases($b,$data));dbReject(403,fn()=>datasetDatabases([...$a,'features'=>'{"database":false}'],$data));dbReject(403,fn()=>datasetDatabases([...$a,'features'=>'{"data_lab":false}'],$data));
query('INSERT INTO project_connections VALUES(?,?,?,?,?)',[$pid,'127.0.0.1','unused','unused',encryptSecret('test')]);query('INSERT INTO connections VALUES(?,?,?,?,?)',[$b['id'],'127.0.0.1','unused','unused',encryptSecret('other-secret')]);
dbCheck(array_column(datasetDatabases($a,$data)['databases'],'scope')===['project'],'Never list another personal connection');query('INSERT INTO connections VALUES(?,?,?,?,?)',[$a['id'],'127.0.0.1','unused','unused',encryptSecret('test')]);$sources=datasetDatabases($a,$data);dbCheck(array_column($sources['databases'],'scope')===['project','personal'],'Explicit source scopes');dbCheck(array_keys($sources['databases'][0])===['scope','name'],'No credentials or infrastructure disclosed');dbReject(422,fn()=>datasetDatabaseConnection($a,[...$data,'scope'=>'someone-else']));
$columns=[['Field'=>'code','Type'=>'varchar(10)'],['Field'=>'value','Type'=>'decimal(10,2)'],['Field'=>'missing','Type'=>'int']];$rows=[['code'=>'00123','value'=>'8.50','missing'=>null],['code'=>'00456','value'=>null,'missing'=>null]];
$c=datasetDatabaseContent($columns,$rows);dbCheck($c['rows'][0]['code']==='00123'&&$c['rows'][0]['value']===8.5&&$c['rows'][1]['value']===null,'Typed copy preserves codes, decimals and NULL');dbCheck($c['columns'][2]['type']==='number','All-NULL SQL numeric columns retain their schema');dbCheck(count(datasetDatabaseContent($columns,[])['columns'])===3,'Empty tables retain all columns');
$precise=datasetDatabaseContent([['Field'=>'n','Type'=>'bigint']],[['n'=>'18446744073709551615']]);dbCheck($precise['rows'][0]['n']==='18446744073709551615'&&$precise['columns'][0]['type']==='text','Large identifiers never lose precision');$decimal=datasetDatabaseContent([['Field'=>'n','Type'=>'decimal(30,18)']],[['n'=>'1.123456789012345678']]);dbCheck($decimal['rows'][0]['n']==='1.123456789012345678','High precision remains exact text');
dbReject(422,fn()=>datasetDatabaseContent(array_fill(0,51,$columns[0]),[]));dbReject(422,fn()=>datasetDatabaseContent([['Field'=>'__proto__','Type'=>'text']],[]));dbReject(422,fn()=>datasetDatabaseContent([['Field'=>'binary','Type'=>'blob']],[['binary'=>"\xFF"]]));
$dsn=getenv('MYSQL_SCHEMA_TEST_DSN');if($dsn){
 if($dsn!=='mysql:host=127.0.0.1;port=3306;dbname=ectro_schema_test')throw new RuntimeException('Only the isolated test schema is allowed.');
 $pdo=new PDO($dsn,'schema_test','disposable-schema-test-password',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
 try{
  $pdo->exec('CREATE TABLE dataset_import_read (id INT PRIMARY KEY,code VARCHAR(10),value DECIMAL(10,2) NULL)');$pdo->exec("INSERT INTO dataset_import_read VALUES(1,'00123',8.50),(2,'00456',NULL),(3,'00789',1.25)");$pdo->exec('CREATE TABLE dataset_import_empty (code VARCHAR(10),amount INT NULL)');
  query('UPDATE project_connections SET db_name=?,username=?,secret=? WHERE project_id=?',['ectro_schema_test','schema_test',encryptSecret('disposable-schema-test-password'),$pid]);
  query('INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value',['lab_limits',json_encode(['rows'=>2])]);
  dbCheck(in_array('dataset_import_read',datasetDatabaseTables($a,$data)['tables'],true),'Read project table list');$read=datasetDatabaseRead($a,[...$data,'table'=>'dataset_import_read']);dbCheck(count($read['content']['rows'])===2&&$read['truncated']&&$read['limit']===2,'Configured limit explicitly reports partial tables');dbCheck($read['content']['rows'][0]['code']==='00123'&&$read['content']['rows'][0]['value']===8.5,'Real PDO conversion');
  $empty=datasetDatabaseRead($a,[...$data,'table'=>'dataset_import_empty']);dbCheck($empty['content']['rows']===[]&&count($empty['content']['columns'])===2,'Real empty table schema');dbReject(422,fn()=>datasetDatabaseRead($a,[...$data,'table'=>'dataset_import_read; DROP TABLE x']));dbReject(404,fn()=>datasetDatabaseRead($a,[...$data,'table'=>'dataset_import_missing']));dbReject(422,fn()=>datasetDatabaseTables($a,['project'=>$unconnected,'scope'=>'project']));
  query('UPDATE connections SET db_name=?,username=?,secret=? WHERE user_id=?',['ectro_schema_test','schema_test',encryptSecret('disposable-schema-test-password'),$a['id']]);dbCheck(count(datasetDatabaseRead($a,[...$data,'scope'=>'personal','table'=>'dataset_import_read'])['content']['rows'])===2,'Explicit personal source');
  $saved=labSave($a,['project'=>$pid,'kind'=>'dataset','name'=>'Copy','content'=>$read['content']]);dbCheck(labObject($a,$saved['id'])['content']['rows'][0]['code']==='00123','Imported copy persists through normal versioned lab storage');dbCheck((int)$pdo->query('SELECT COUNT(*) FROM dataset_import_read')->fetchColumn()===3,'Source table remains unchanged');
 }finally{$pdo->exec('DROP TABLE IF EXISTS dataset_import_read');$pdo->exec('DROP TABLE IF EXISTS dataset_import_empty');}
}else echo "Real MariaDB import checks run in CI with the isolated schema service.\n";
echo "$checks database import checks passed.\n";
